INSERT INTO `Setting` (`id`, `key`, `value`, `updatedAt`) VALUES
('SEASONAL_OFFER_DATA', 'SEASONAL_OFFER_DATA', '{\"slug\":\"seasonal-offer\",\"title\":\"বিশেষ অফারে অরিজিনাল বিউটি কম্বো প্যাকেজ!\",\"subtitle\":\"সীমিত সময়ের জন্য ছাড়! ১০০% অরিজিনাল প্রোডাক্ট দ্রুত ক্যাশ অন ডেলিভারিতে পান।\",\"videoUrl\":\"https://www.w3schools.com/html/mov_bbb.mp4\",\"productTitle\":\"প্রিমিয়াম বিউটি ও স্কিনকেয়ার গ্লো সেট\",\"productPrice\":\"1250\",\"originalPrice\":\"1850\",\"productImages\":[\"data:image/png;base64\",\"\"],\"description\":\"আমাদের এই বিশেষ প্যাকেজে রয়েছে ত্বকের যত্ন ও উজ্জ্বলতার জন্য প্রয়োজনীয় প্রিমিয়াম উপাদান। নিয়মিত ব্যবহারে পাবেন দাগহীন, উজ্জ্বল ও সতেজ ত্বক।\",\"bulletPoints\":\"১০০% অরিজিনাল প্রোডাক্ট|ত্বক হবে সতেজ ও উজ্জ্বল|কোনো সাইড ইফেক্ট নেই|সারাদেশে ক্যাশ অন ডেলিভারি\",\"insideDhakaShipping\":\"70\",\"subAreaShipping\":\"100\",\"outsideDhakaShipping\":\"130\",\"isActive\":true}', '2026-08-07 11:58:22.000');
